// Prefill of the CV builder and the cover letter tool from the Vorlagen-Archiv (/vorlagen/bewerbung/<job>/).
// The job pages link to the tools with ?vorlage=<id>[&brief=<n>]; the example data is a static JSON file of the
// same origin (/vorlagen/data/<id>.json, generated by network/tools/vorlagen/build.py). Only the example is
// fetched – nothing about the user leaves the device, and the tools never overwrite a saved draft or a
// remembered sender without asking (see cv-builder.js / cover-letter.js).
import { el, icon } from './dom.js';

const ID_RE = /^(en-)?[a-z0-9]+(-[a-z0-9]+)*$/;
const PHOTO_RE = /^\/assets\/vorlagen\/avatar\/[a-z0-9-]+\.png$/;

/** {id, letter} from the address bar, or null. letter is 0-based. */
export function vorlageParam(search = location.search) {
  const p = new URLSearchParams(search);
  const id = (p.get('vorlage') || '').trim();
  if (!id || id.length > 90 || !ID_RE.test(id)) return null;
  const n = parseInt(p.get('brief') || '1', 10);
  return { id, letter: Number.isFinite(n) ? Math.min(Math.max(n - 1, 0), 5) : 0 };
}

/** Loads the example data for the current ?vorlage=… → {id, letter, data} or null (no param / not found / offline). */
export async function loadVorlage() {
  const q = vorlageParam();
  if (!q) return null;
  try {
    // the index lists the existing ids, so a stale link never produces a failing request
    const idx = await (await fetch('/vorlagen/data/index.json', { credentials: 'same-origin' })).json();
    if (!Array.isArray(idx?.ids) || !idx.ids.includes(q.id)) throw new Error('unknown template');
    const res = await fetch(`/vorlagen/data/${q.id}.json`, { credentials: 'same-origin' });
    if (!res.ok) throw new Error('HTTP ' + res.status);
    const data = await res.json();
    if (!data || data.v !== 1 || data.id !== q.id) throw new Error('bad data');
    return { ...q, data };
  } catch (err) {
    console.warn('vorlage', q.id, err);
    return { ...q, data: null };
  }
}

/** The placeholder portrait of an example CV as a Blob (PNG), or null. */
export async function vorlagePhoto(url) {
  if (typeof url !== 'string' || !PHOTO_RE.test(url)) return null;
  try {
    const res = await fetch(url, { credentials: 'same-origin' });
    if (!res.ok) return null;
    const blob = await res.blob();
    return blob.type === 'image/png' ? blob : new Blob([blob], { type: 'image/png' });
  } catch { return null; }
}

/** Back to the job page the example came from. */
export function vorlagePage(id, lang) {
  return lang === 'en' || id.startsWith('en-') ? '/en/templates/' : '/vorlagen/bewerbung/';
}

/** Notice at the top of a tool stage: what was loaded, what to do first. actions: [Node]. */
export function vorlageNotice(lang, text, actions = []) {
  const de = lang === 'de';
  return el('div', { class: 'tpl-note arc-vl-note', role: 'status' }, icon('file'),
    el('div', {}, el('strong', {}, text.title), el('p', {}, text.body),
      actions.length ? el('div', { class: 'img-btn-row' }, ...actions) : null,
      el('p', { class: 'img-muted' }, de ? 'Alle Personen und Kontaktdaten im Beispiel sind erfunden.' : 'All people and contact details in the example are fictional.')));
}

/** Message when the example could not be loaded (offline, unknown id). */
export function vorlageMissing(lang) {
  return el('p', { class: 'tpl-note', role: 'status' }, icon('alert'), el('span', {}, lang === 'de'
    ? 'Die Vorlage konnte nicht geladen werden (offline oder nicht mehr vorhanden). Du kannst das Formular trotzdem ausfüllen.'
    : 'The template could not be loaded (offline or no longer available). You can still fill in the form.'));
}
